<?php
require_once __DIR__.'/../includes/config.php';
if(session_status()===PHP_SESSION_NONE)session_start();
if(empty($_SESSION['admin_id']) && empty($_SESSION['admin_logged_in'])){header('Location: admin-login.php');exit;}
function bh($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='setting'){
  $key=trim($_POST['key']??'');$value=trim($_POST['value']??'');
  $allowed=['customer_markup_percent','restaurant_commission_percent','rider_base_payout','delivery_fee_per_km','currency'];
  if(!in_array($key,$allowed,true)){$err='Invalid business setting.';}
  elseif($value===''){$err='Setting value is required.';}
  elseif(in_array($key,['customer_markup_percent','restaurant_commission_percent'],true) && ((float)$value<0 || (float)$value>100)){$err='Percentage must be between 0 and 100.';}
  elseif(in_array($key,['rider_base_payout','delivery_fee_per_km'],true) && (float)$value<0){$err='Amount cannot be negative.';}
  else{$s=$conn->prepare('INSERT INTO business_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');if($s){$s->bind_param('ss',$key,$value);if($s->execute())$msg='Business setting saved.';else$err='Unable to save setting.';$s->close();}else $err='Run the business database migrations first.';}
 }elseif($action==='coupon'){
  $code=strtoupper(trim($_POST['code']??''));$type=$_POST['discount_type']??'percent';$value=(float)($_POST['discount_value']??0);$min=(float)($_POST['minimum_order']??0);$expiry=trim($_POST['expires_at']??'');
  if($code==='')$err='Coupon code is required.';else{$s=$conn->prepare('INSERT INTO coupons(code,discount_type,discount_value,minimum_order,expires_at,is_active) VALUES(?,?,?,?,?,1)');if($s){$s->bind_param('ssdds',$code,$type,$value,$min,$expiry);if($s->execute())$msg='Coupon created.';else$err='Unable to create coupon. Check whether the code already exists.';$s->close();}else $err='Run database/humsafar_business_upgrade.sql first.';}
 }elseif($action==='support'){
  $id=(int)$_POST['ticket_id'];$status=$_POST['status']??'in_progress';$reply=trim($_POST['reply']??'');$s=$conn->prepare('UPDATE support_tickets SET status=?,admin_reply=? WHERE id=?');if($s){$s->bind_param('ssi',$status,$reply,$id);$s->execute();$s->close();$msg='Support ticket updated.';}else $err='Support table is not installed.';
 }
}
$settings=[];$q=$conn->query('SELECT setting_key,setting_value FROM business_settings ORDER BY setting_key');if($q)while($r=$q->fetch_assoc())$settings[]=$r;
$coupons=[];$q=$conn->query('SELECT * FROM coupons ORDER BY id DESC LIMIT 30');if($q)while($r=$q->fetch_assoc())$coupons[]=$r;
$tickets=[];$q=$conn->query("SELECT * FROM support_tickets WHERE status NOT IN ('closed','resolved') ORDER BY id DESC LIMIT 30");if($q)while($r=$q->fetch_assoc())$tickets[]=$r;
$rate=50;$markup=0;$commission=15;$riderPay=80;$currency='PKR';
$q=$conn->query("SELECT setting_key,setting_value FROM business_settings WHERE setting_key IN ('delivery_fee_per_km','customer_markup_percent','restaurant_commission_percent','rider_base_payout','currency')");
if($q)while($r=$q->fetch_assoc()){if($r['setting_key']==='delivery_fee_per_km')$rate=(float)$r['setting_value'];elseif($r['setting_key']==='customer_markup_percent')$markup=(float)$r['setting_value'];elseif($r['setting_key']==='restaurant_commission_percent')$commission=(float)$r['setting_value'];elseif($r['setting_key']==='rider_base_payout')$riderPay=(float)$r['setting_value'];elseif($r['setting_key']==='currency')$currency=$r['setting_value'];}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Management</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>body{margin:0;background:#f7f7f9;font-family:Segoe UI,Arial;color:#222}.page{margin-left:218px;padding:30px}.wrap{max-width:1150px}.title{font-size:30px;font-weight:900;margin:0}.sub{color:#777}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:22px}.card{background:#fff;border:1px solid #f0dfe6;border-radius:15px;padding:20px;box-shadow:0 5px 18px #00000008}.wide{grid-column:1/-1}.field{margin:10px 0}.field label{display:block;font-size:11px;font-weight:800;margin-bottom:5px}.hint{font-size:12px;color:#777;line-height:1.5}.input,select,textarea{width:100%;padding:10px;border:1px solid #ddd;border-radius:8px;box-sizing:border-box;font:inherit}.btn{border:0;background:#ed0038;color:#fff;padding:10px 16px;border-radius:8px;font-weight:800;cursor:pointer}.msg{padding:11px;border-radius:8px;margin:15px 0;background:#eaf8ef;color:#176c36}.err{background:#fff0f3;color:#a0002d}.table{width:100%;border-collapse:collapse;font-size:12px}.table th,.table td{text-align:left;padding:9px;border-bottom:1px solid #eee}.pill{padding:4px 8px;border-radius:20px;background:#fff0f4;color:#ed0038;font-size:10px;font-weight:800}.distance{display:flex;align-items:center;gap:10px;background:#fff4f7;border:1px solid #ffd6e2;border-radius:10px;padding:12px;margin-top:12px}.distance i{color:#ed0038;font-size:20px}.formula{background:#f8f8fa;border-radius:10px;padding:12px;margin-top:12px;font-size:12px;line-height:1.7}@media(max-width:900px){.page{margin-left:0}.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><?php include __DIR__.'/admin-sidebar.php';?><main class="page"><div class="wrap"><h1 class="title">Business Management</h1><p class="sub">Control customer pricing, restaurant commission, rider payout and distance-based delivery pricing.</p><?php if($msg):?><div class="msg"><?=bh($msg)?></div><?php endif;?><?php if($err):?><div class="msg err"><?=bh($err)?></div><?php endif;?><div class="grid"><section class="card"><h3>Customer Pricing</h3><p class="hint">Restaurant owners keep their base menu price. This percentage is added only to the price shown to customers.</p><form method="post"><input type="hidden" name="action" value="setting"><input type="hidden" name="key" value="customer_markup_percent"><div class="field"><label>Customer Markup (%)</label><input class="input" name="value" type="number" min="0" max="100" step="0.01" value="<?=bh($markup)?>" required></div><button class="btn">Save Customer Markup</button></form><div class="formula"><b>Example:</b> Restaurant base PKR 100 + <?=$markup?>% markup = <b>PKR <?=bh(number_format($markup?100*(1+$markup/100):100,2))?></b> customer price.</div></section><section class="card"><h3>Delivery & Rider</h3><form method="post"><input type="hidden" name="action" value="setting"><div class="field"><label>Setting</label><select name="key"><option value="delivery_fee_per_km">Delivery Fee per KM</option><option value="rider_base_payout">Rider Base Payout</option></select></div><div class="field"><label>Value</label><input class="input" name="value" value="<?=bh($rate)?>" required></div><p class="hint">Delivery uses started kilometres. Example: 2.1 km × PKR 50/km = PKR 150.</p><button class="btn">Save Setting</button></form><div class="distance"><i class="fa-solid fa-route"></i><div><b>Current: PKR <?=bh(number_format($rate,2))?> / km</b><br><span class="hint">Rider base payout: PKR <?=bh(number_format($riderPay,2))?></span></div></div></section><section class="card"><h3>Restaurant Commission</h3><p class="hint">This commission is used for restaurant settlement; it is separate from the customer markup.</p><form method="post"><input type="hidden" name="action" value="setting"><input type="hidden" name="key" value="restaurant_commission_percent"><div class="field"><label>Commission (%)</label><input class="input" name="value" type="number" min="0" max="100" step="0.01" value="<?=bh($commission)?>" required></div><button class="btn">Save Commission</button></form><div class="formula"><b>Current:</b> <?=$commission?>% platform commission. Customer markup and restaurant commission are calculated independently.</div></section><section class="card"><h3>Create Coupon</h3><form method="post"><input type="hidden" name="action" value="coupon"><div class="field"><label>Code</label><input class="input" name="code" placeholder="HUMSAFAR20" required></div><div class="field"><label>Discount</label><select name="discount_type"><option value="percent">Percentage</option><option value="fixed">Fixed PKR</option></select></div><div class="field"><input class="input" name="discount_value" type="number" step="0.01" placeholder="20" required></div><div class="field"><label>Minimum Order</label><input class="input" name="minimum_order" type="number" step="0.01" value="0"></div><div class="field"><label>Expiry</label><input class="input" name="expires_at" type="datetime-local"></div><button class="btn">Create Coupon</button></form></section><section class="card"><h3>Installed Settings</h3><?php foreach($settings as $s):?><p><b><?=bh($s['setting_key'])?></b><br><span class="pill"><?=bh($s['setting_value'])?></span></p><?php endforeach;?></section><section class="card wide"><h3>Coupons</h3><table class="table"><tr><th>Code</th><th>Type</th><th>Value</th><th>Minimum</th><th>Expiry</th><th>Status</th></tr><?php foreach($coupons as $c):?><tr><td><b><?=bh($c['code'])?></b></td><td><?=bh($c['discount_type'])?></td><td><?=bh($c['discount_value'])?></td><td>PKR <?=bh($c['minimum_order'])?></td><td><?=bh($c['expires_at'])?></td><td><?=((int)$c['is_active']?'Active':'Off')?></td></tr><?php endforeach;if(!$coupons):?><tr><td colspan="6">No coupons yet.</td></tr><?php endif;?></table></section><section class="card wide"><h3>Open Support Tickets</h3><?php foreach($tickets as $t):?><form method="post" style="border-bottom:1px solid #eee;padding:12px 0"><input type="hidden" name="action" value="support"><input type="hidden" name="ticket_id" value="<?=bh($t['id'])?>"><b>#<?=bh($t['id'])?> · <?=bh($t['subject'])?></b> <span class="pill"><?=bh($t['role'])?></span><p><?=nl2br(bh($t['message']))?></p><select name="status"><option>in_progress</option><option>resolved</option><option>closed</option></select><textarea name="reply" placeholder="Admin reply" style="margin:8px 0"></textarea><button class="btn">Update Ticket</button></form><?php endforeach;if(!$tickets):?><p>No open tickets.</p><?php endif;?></section></div></div></main></body></html>